/* T3 Chat Theme — Tailwind v3 (hsl) */
/* Channel triplets — consume via hsl(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* T3 Chat Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 299.97 50.87% 97.71%;
    --foreground: 295.99 57.01% 21.54%;
    --card: 299.97 50.87% 97.71%;
    --card-foreground: 295.99 57.01% 21.54%;
    --popover: 300 50% 100%;
    --popover-foreground: 295.99 57.01% 21.54%;
    --primary: 333.3 42.83% 45.9%;
    --primary-foreground: 300 50% 100%;
    --secondary: 314.61 64.46% 85.81%;
    --secondary-foreground: 295.86 40% 34%;
    --muted: 310.5 57.72% 93.35%;
    --muted-foreground: 295.56 31.58% 39.92%;
    --accent: 314.61 64.46% 85.81%;
    --accent-foreground: 295.86 40% 34%;
    --destructive: 357.38 45.39% 46.03%;
    --destructive-foreground: 300 50% 100%;
    --border: 304.86 60.25% 84.27%;
    --input: 317.25 47.19% 83.06%;
    --ring: 332.99 71.83% 50.03%;
    --chart-1: 318 74.42% 48.73%;
    --chart-2: 273.71 92.69% 37.78%;
    --chart-3: 197.52 32.49% 24.5%;
    --chart-4: 43.17 73.36% 65.26%;
    --chart-5: 27.29 87.75% 66.11%;
    --radius: 0.5rem;
    --sidebar: 290 56.7% 93.51%;
    --sidebar-foreground: 327.05 78.51% 37.36%;
    --sidebar-primary: 240.31 11.41% 30.82%;
    --sidebar-primary-foreground: 320.07 41.47% 96.57%;
    --sidebar-accent: 300 0% 97.37%;
    --sidebar-accent-foreground: 240.31 11.41% 30.82%;
    --sidebar-border: 330 0% 92.15%;
    --sidebar-ring: 332.99 71.83% 50.03%;
    --font-sans:
      ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
      Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
      "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono:
      ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
      "Courier New", monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 269.99 14.72% 13.24%;
    --foreground: 272.33 29.36% 82.07%;
    --card: 269.82 11.87% 17.06%;
    --card-foreground: 324.56 24.04% 82.13%;
    --popover: 320.47 19.2% 4.63%;
    --popover-foreground: 325.68 32.01% 95.32%;
    --primary: 332.04 99.92% 31.91%;
    --primary-foreground: 329.43 59.5% 84.94%;
    --secondary: 273.74 15.05% 20.39%;
    --secondary-foreground: 270.03 32.29% 83.48%;
    --muted: 272.64 13.03% 15.08%;
    --muted-foreground: 268.86 21.9% 75.96%;
    --accent: 272.14 20.32% 26.51%;
    --accent-foreground: 325.68 32.01% 95.32%;
    --destructive: 351.11 46.28% 12.96%;
    --destructive-foreground: 300 50% 100%;
    --border: 326.3 10.57% 21.67%;
    --input: 311.97 8.95% 22.49%;
    --ring: 332.99 71.83% 50.03%;
    --chart-1: 333.3 42.83% 45.9%;
    --chart-2: 273.33 53.82% 54.46%;
    --chart-3: 30.04 79.3% 54.55%;
    --chart-4: 279.93 63.72% 60.07%;
    --chart-5: 339.63 74.63% 54.58%;
    --radius: 0.5rem;
    --sidebar: 308.22 20.59% 8.16%;
    --sidebar-foreground: 327.25 26.74% 83.48%;
    --sidebar-primary: 224.36 76.88% 48.37%;
    --sidebar-primary-foreground: 300 50% 100%;
    --sidebar-accent: 318.05 24.14% 12.08%;
    --sidebar-accent-foreground: 300 0% 96.06%;
    --sidebar-border: 0 0% 0%;
    --sidebar-ring: 332.99 71.83% 50.03%;
    --font-sans:
      ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
      Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
      "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono:
      ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
      "Courier New", monospace;
    --shadow-color: 0 0% 0%;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  }

}
